def find_maximum_sum(matrix):
    """
    Given a matrix, find the maximum sum of any sub-matrix by breaking out of the loop.

    Args:
    matrix (list[list[int]]): A 2D matrix containing integer values.

    Returns:
    int: The maximum sum of any sub-matrix.

    """

### Solution:


    rows = len(matrix)
    cols = len(matrix[0])
    max_sum = float('-inf')

    for i in range(rows):
        for j in range(cols):
            for k in range(i, rows):
                for l in range(j, cols):
                    curr_sum = 0
                    for x in range(i, k + 1):
                        for y in range(j, l + 1):
                            curr_sum += matrix[x][y]
                            if curr_sum > max_sum:
                                max_sum = curr_sum

    return max_sum

