def concatenate_strings_by_length(strings):
    """
    This function takes a list of strings as input and concatenates them based on their length.
    The concatenated strings are returned as a single string.

    Args:
    strings (list): A list of strings to be concatenated

    Returns:
    string: The concatenated string
    """

### Solution:

    concatenated_string = ''
    lengths = [len(string) for string in strings]  # List comprehension to get lengths of each string
    sorted_indices = sorted(range(len(strings)), key=lambda x: lengths[x], reverse=True)
    # Sorting indices based on string length in descending order

    for i in sorted_indices:
        string = strings[i]
        if len(string) == 1:
            concatenated_string += string + "_"
        elif len(string) % 2 == 0:
            for j in range(len(string) - 1):
                if j % 2 == 0:
                    concatenated_string += string[j]
        else:
            for j in range(len(string)):
                if j % 2 != 0:
                    concatenated_string += string[j]

    return concatenated_string

