def chef_special_menu(menu):

    """Chef exercise: Finding the intersections of dishes in multiple menus"""

### Solution:


    # Initializing an empty set to hold the common dishes
    common_dishes = set()

    # Checking each menu one by one
    for i in range(len(menu)):

        # Using nested while loops and indexing tuples to compare dishes
        j = 0
        while j < len(menu[i]):
            k = 0
            while k < len(menu[i][j]):
                # If the dish is already common, no need to check further
                if menu[i][j][k] in common_dishes:
                    break
                # Checking if the dish is present in all other menus
                present_in_all = True
                for x in range(len(menu)):
                    if x != i:
                        if menu[i][j][k] not in menu[x]:
                            present_in_all = False
                            break
                # If the dish is present in all menus, adding it to the common set
                if present_in_all:
                    common_dishes.add(menu[i][j][k])
                k += 1
            j += 1

    # Returning the common dishes
    return common_dishes

