def modify_elements(numbers, letters):

    """This exercise requires you to modify elements in a list of numbers using nested loops and list comprehensions"""

### Solution:


    # Use list comprehension to create a new list with all even numbers squared
    square_evens = [num ** 2 for num in numbers if num % 2 == 0]

    # Use nested loops to modify the original list and replace all odd numbers with their corresponding letter
    for i in range(len(numbers)):
        if numbers[i] % 2 != 0:
