def calculate_total_species(matrix):
    """Given a 2D matrix representing a grid of species in a habitat, 
    calculates the total number of unique species present in the grid.

    :param matrix: The 2D matrix representing the grid of species.
    :type matrix: list of lists

    :return: The total number of unique species in the grid.
    :rtype: int
    """

### Solution:

    if not matrix:
        return 0

    total_species = 0
    visited_species = set()

    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            if (i, j) in visited_species:
                continue

            current_species = matrix[i][j]

            if current_species not in visited_species:
                total_species += 1
                visited_species.add(current_species)

            for x in range(i+1, len(matrix)):
                for y in range(len(matrix[x])):
                    if matrix[x][y] == current_species and (x, y) not in visited_species:
                        visited_species.add((x, y))

    return total_species

