def draw_circle(size):

    """This exercise requires the artist to draw a circle using nested loops and handle infinite loops properly."""

### Solution:


    radius = size // 2
    center = size // 2

    for y in range(size):
        for x in range(size):
            distance = ((x - center) ** 2 + (y - center) ** 2) ** 0.5
            if distance <= radius:
                print("*", end="")
            else:
                print(" ", end="")

        print()

